75	/// Get parser source context with bounds checking.
76	///
77	/// Returns `Some((start_position, source_text))` if the current position is valid,
78	/// or `None` if the position is out of bounds.
79	fn get_source_context<'a>(p: &'a MarkdownParser) -> Option<(usize, &'a str)> {
80	    let start: usize = p.cur_range().start().into();
81	    let source = p.source().text();
82	    if start > source.len() {
83	        return None;
84	    }
85	    Some((start, source))
86	}
