}", "newString": "/// Scan a backtick fence's info string for a stray backtick character.
///
/// Assumes the current token is the opening fence (any leading indent already
/// skipped). Consumes tokens, so it must be run inside a [`MarkdownParser::lookahead`].
///
/// Returns the range of the first backtick found in the info string, or `None`
/// for tilde fences, non-fences, or backtick fences with a clean info string.
fn scan_info_string_stray_backtick(p: &mut MarkdownParser) -> Option<TextRange> {
    if p.at(TRIPLE_TILDE) {
        return None;
    }

    if p.at(T!["```"]) {
        p.bump(T!["```"]);
    } else if p.at(BACKTICK) {
        p.bump(BACKTICK);
    } else {
        return None;
    }

    while !p.at_inline_end() {
        if p.at(BACKTICK) || p.at(T!["```"]) {
            return Some(p.cur_range());
        }
        p.bump(p.cur());
    }

    None
}

pub(crate) fn info_string_has_backtick(p: &mut MarkdownParser) -> bool {
    p.lookahead(|p| scan_info_string_stray_backtick(p).is_some())
}

/// If the current line opens a backtick code fence whose info string contains a
/// backtick character, emit the [`backtick_in_fence_info_string`] diagnostic and
/// return `true`. The offending line is left untouched for the caller to parse
/// as a paragraph, per CommonMark §4.5.
///
/// Returns `false` (and emits nothing) for tilde fences, non-fences, backtick
/// fences with a clean info string, or lines indented too far to open a fence.
pub(crate) fn emit_backtick_fence_info_diagnostic(p: &mut MarkdownParser) -> bool {
    let stray_range = p.lookahead(|p| {
        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);
        match detect_fence(p.source_after_current()) {
            Some(('`', _)) => scan_info_string_stray_backtick(p),
            _ => None,
        }
    });

    match stray_range {
        Some(range) => {
            p.error(backtick_in_fence_info_string(p, range));
            true
        }
        None => false,
    }
